// Strategy interface: how the next song in a playlist is chosen.
interface PlaybackStrategy {
    void reset(Playlist playlist);     // initializes ordering state for a fresh playlist
    Song next(Playlist playlist);        // returns the next song to play
}

// Plays songs in playlist order, wrapping back to the start at the end.
class SequentialPlaybackStrategy implements PlaybackStrategy {
    private int index = 0; // position of the next song to play

    @Override
    public void reset(Playlist playlist) { index = 0; } // start over from the first song

    @Override
    public Song next(Playlist playlist) {
        Song song = playlist.getSongs().get(index);     // the song at the current position
        index = (index + 1) % playlist.size();             // advance, wrapping around at the end
        return song; // hand back the chosen song
    }
}

// Plays a random permutation of the whole playlist, reshuffling only once every song has played.
class ShufflePlaybackStrategy implements PlaybackStrategy {
    private java.util.List<Integer> order = new java.util.ArrayList<>(); // the current cycle's shuffled index order
    private int pointer = 0;                                                // position within the current cycle
    private final java.util.Random random;                                     // source of randomness

    public ShufflePlaybackStrategy(java.util.Random random) {
        this.random = random; // injected so behavior can be made deterministic in tests
    }

    @Override
    public void reset(Playlist playlist) {
        order = shuffledIndices(playlist.size(), -1); // build a fresh shuffled order, no previous last song yet
        pointer = 0;                                     // start at the beginning of the new cycle
    }

    @Override
    public Song next(Playlist playlist) {
        if (pointer >= order.size()) {                                       // current cycle is exhausted
            int lastPlayedIndex = order.get(order.size()-1);                   // last song of the previous cycle
            order = shuffledIndices(playlist.size(), lastPlayedIndex);             // reshuffle, avoiding a same-song repeat at the boundary
            pointer = 0;                                                             // restart the pointer for the new cycle
        }
        int songIndex = order.get(pointer);                                     // index of the next song in this cycle
        pointer++;                                                                 // advance within the cycle
        return playlist.getSongs().get(songIndex); // hand back the chosen song
    }

    // Fisher-Yates shuffle of [0, size), reshuffled if needed so the first entry never equals avoidFirst.
    private java.util.List<Integer> shuffledIndices(int size, int avoidFirst) {
        java.util.List<Integer> indices = new java.util.ArrayList<>();                 // 0..size-1
        for (int i = 0; i < size; i++) indices.add(i);                                    // fill with every index once
        for (int i = indices.size()-1; i > 0; i--) {                                       // Fisher-Yates shuffle
            int j = random.nextInt(i + 1);                                                     // pick a random earlier or equal position
            int temp = indices.get(i); indices.set(i, indices.get(j)); indices.set(j, temp);      // swap
        }
        if (size > 1 && indices.get(0) == avoidFirst) {                                       // avoid an immediate repeat at the cycle boundary
            int temp = indices.get(0); indices.set(0, indices.get(1)); indices.set(1, temp);        // swap the first two entries
        }
        return indices; // the new cycle's play order
    }
}

// Observer interface: reacts to playback lifecycle events.
interface PlaybackObserver {
    void onSongPlayed(Song song);                        // a song started playing
    void onSkipRejected(String userId, String reason);      // a skip request was rejected
}

// Simple observer that prints events to the console.
class ConsolePlaybackObserver implements PlaybackObserver {
    @Override
    public void onSongPlayed(Song song) {
        System.out.println("Now playing: " + song.getTitle());
    }

    @Override
    public void onSkipRejected(String userId, String reason) {
        System.out.println("Skip rejected for " + userId + ": " + reason);
    }
}

