#include <string>
#include <vector>
#include <random>
#include <iostream>
using namespace std;

// Strategy interface: how the next song in a playlist is chosen.
class PlaybackStrategy {
public:
    virtual void reset(Playlist& playlist) = 0;
    virtual Song next(Playlist& playlist) = 0;
    virtual ~PlaybackStrategy() {}
};

// Plays songs in playlist order, wrapping back to the start at the end.
class SequentialPlaybackStrategy : public PlaybackStrategy {
    int index = 0; // position of the next song to play

public:
    void reset(Playlist& playlist) override { index = 0; } // start over from the first song

    Song next(Playlist& playlist) override {
        Song song = playlist.songs[index];             // the song at the current position
        index = (index + 1) % playlist.size();            // advance, wrapping around at the end
        return song; // hand back the chosen song
    }
};

// Plays a random permutation of the whole playlist, reshuffling only once every song has played.
class ShufflePlaybackStrategy : public PlaybackStrategy {
    vector<int> order;    // the current cycle's shuffled index order
    int pointer = 0;         // position within the current cycle
    mt19937& rng;               // injected source of randomness, so behavior can be made deterministic in tests

    vector<int> shuffledIndices(int size, int avoidFirst) {
        vector<int> indices;                                                  // 0..size-1
        for (int i = 0; i < size; i++) indices.push_back(i);                     // fill with every index once
        for (int i = (int)indices.size()-1; i > 0; i--) {                        // Fisher-Yates shuffle
            uniform_int_distribution<int> dist(0, i);                                // pick a random earlier or equal position
            int j = dist(rng);
            swap(indices[i], indices[j]);                                                // swap
        }
        if (size > 1 && indices[0] == avoidFirst) {                                    // avoid an immediate repeat at the cycle boundary
            swap(indices[0], indices[1]);                                                 // swap the first two entries
        }
        return indices; // the new cycle's play order
    }

public:
    ShufflePlaybackStrategy(mt19937& randomGen) : rng(randomGen) {} // store the injected rng reference

    void reset(Playlist& playlist) override {
        order = shuffledIndices(playlist.size(), -1); // build a fresh shuffled order, no previous last song yet
        pointer = 0;                                     // start at the beginning of the new cycle
    }

    Song next(Playlist& playlist) override {
        if (pointer >= (int)order.size()) {                                       // current cycle is exhausted
            int lastPlayedIndex = order[order.size()-1];                            // last song of the previous cycle
            order = shuffledIndices(playlist.size(), lastPlayedIndex);                  // reshuffle, avoiding a same-song repeat at the boundary
            pointer = 0;                                                                  // restart the pointer for the new cycle
        }
        int songIndex = order[pointer];                                              // index of the next song in this cycle
        pointer++;                                                                      // advance within the cycle
        return playlist.songs[songIndex]; // hand back the chosen song
    }
};

// Observer interface: reacts to playback lifecycle events.
class PlaybackObserver {
public:
    virtual void onSongPlayed(const Song& song) = 0;
    virtual void onSkipRejected(const string& userId, const string& reason) = 0;
    virtual ~PlaybackObserver() {}
};

// Simple observer that prints events to the console.
class ConsolePlaybackObserver : public PlaybackObserver {
public:
    void onSongPlayed(const Song& song) override {
        cout << "Now playing: " << song.title << endl;
    }
    void onSkipRejected(const string& userId, const string& reason) override {
        cout << "Skip rejected for " << userId << ": " << reason << endl;
    }
};

