// Custom exceptions for the realistic failure modes.
class SkipLimitExceededException extends RuntimeException {
    public SkipLimitExceededException(String msg) { super(msg); }
}
class EmptyPlaylistException extends RuntimeException {
    public EmptyPlaylistException(String msg) { super(msg); }
}
class SongNotFoundException extends RuntimeException {
    public SongNotFoundException(String msg) { super(msg); }
}

// The core playback engine tying every piece together.
class MusicPlayerService {
    private static final int FREE_SKIP_LIMIT = 3;                                              // free tier skips allowed per session
    private final java.util.Map<String, PlaybackSession> sessions = new java.util.HashMap<>();     // sessionId -> PlaybackSession
    private final java.util.List<PlaybackObserver> observers = new java.util.ArrayList<>();           // listeners

    public void addObserver(PlaybackObserver observer) { observers.add(observer); } // register a listener

    // Starts a new playback session against a playlist, using the chosen ordering strategy.
    public PlaybackSession startSession(User user, Playlist playlist, PlaybackStrategy strategy, MusicIdFactory factory) {
        if (playlist.size() == 0) throw new EmptyPlaylistException("Playlist " + playlist.getPlaylistId() + " has no songs"); // must have songs
        strategy.reset(playlist);                                                                  // initialize ordering state for this playlist
        String sessionId = factory.nextSessionId();                                                   // build id
        PlaybackSession session = new PlaybackSession(sessionId, user, playlist, strategy);             // build the session
        sessions.put(sessionId, session);                                                                 // register it
        return session; // hand back the new session
    }

    // Advances to the next song, not counting against the skip limit.
    public synchronized Song play(String sessionId) {
        PlaybackSession session = sessions.get(sessionId);                    // the session to advance
        Song song = session.getStrategy().next(session.getPlaylist());          // ask the strategy for the next song
        session.recordPlay(song.getSongId());                                     // remember it was played
        for (PlaybackObserver obs : observers) obs.onSongPlayed(song);               // notify
        return song; // hand back the chosen song
    }

    // Advances early, subject to the free tier skip limit.
    public synchronized Song skip(String sessionId) {
        PlaybackSession session = sessions.get(sessionId);                                     // the session to advance
        if (session.getUser().getTier() == SubscriptionTier.FREE && session.getSkipCount() >= FREE_SKIP_LIMIT) { // free tier at its limit
            for (PlaybackObserver obs : observers) obs.onSkipRejected(session.getUser().getUserId(), "Skip limit reached");
            throw new SkipLimitExceededException("Free tier skip limit reached for " + session.getUser().getUserId());
        }
        session.incrementSkipCount();                                                              // count this skip
        Song song = session.getStrategy().next(session.getPlaylist());                                // ask the strategy for the next song
        session.recordPlay(song.getSongId());                                                           // remember it was played
        for (PlaybackObserver obs : observers) obs.onSongPlayed(song);                                    // notify
        return song; // hand back the chosen song
    }
}

