import java.util.*;

public class Main {
    public static void main(String[] args) {
        MusicPlayerService service = new MusicPlayerService();
        service.addObserver(new ConsolePlaybackObserver());
        MusicIdFactory factory = new MusicIdFactory();

        Playlist playlist = new Playlist("PL1", "Road Trip");
        playlist.addSong(new Song("S1", "Song One", "Artist A", 200));
        playlist.addSong(new Song("S2", "Song Two", "Artist B", 210));
        playlist.addSong(new Song("S3", "Song Three", "Artist C", 190));
        playlist.addSong(new Song("S4", "Song Four", "Artist D", 220));
        playlist.addSong(new Song("S5", "Song Five", "Artist E", 205));

        User alice = new User("Alice", "Alice", SubscriptionTier.FREE);
        PlaybackSession aliceSession = service.startSession(alice, playlist, new SequentialPlaybackStrategy(), factory);
        service.play(aliceSession.getSessionId());
        service.skip(aliceSession.getSessionId());
        service.skip(aliceSession.getSessionId());
        service.skip(aliceSession.getSessionId());
        try {
            service.skip(aliceSession.getSessionId());
        } catch (SkipLimitExceededException e) {
            System.out.println("Caught expected: " + e.getMessage());
        }

        User bob = new User("Bob", "Bob", SubscriptionTier.PREMIUM);
        Random rng = new Random(42);
        PlaybackSession bobSession = service.startSession(bob, playlist, new ShufflePlaybackStrategy(rng), factory);
        List<String> played = new ArrayList<>();
        for (int i = 0; i < 15; i++) {
            played.add(service.play(bobSession.getSessionId()).getSongId());
        }

        boolean noConsecutiveRepeats = true;
        for (int i = 1; i < played.size(); i++) {
            if (played.get(i).equals(played.get(i-1))) noConsecutiveRepeats = false;
        }
        System.out.println("No consecutive repeats: " + noConsecutiveRepeats);

        boolean everyCycleComplete = true;
        for (int start = 0; start < played.size(); start += 5) {
            Set<String> window = new HashSet<>(played.subList(start, start + 5));
            if (window.size() != 5) everyCycleComplete = false;
        }
        System.out.println("Each cycle contains all songs exactly once: " + everyCycleComplete);
    }
}

