        if (pointer >= order.size()) {
            int lastPlayedIndex = order.get(order.size()-1);
            order = shuffledIndices(playlist.size(), lastPlayedIndex);
            pointer = 0;
        }
        int songIndex = order.get(pointer);
        pointer++;
        return playlist.getSongs().get(songIndex);
    }

    private List<Integer> shuffledIndices(int size, int avoidFirst) {
        List<Integer> indices = new ArrayList<>();
        for (int i = 0; i < size; i++) indices.add(i);
        for (int i = indices.size()-1; i > 0; i--) {
            int j = random.nextInt(i + 1);
            int temp = indices.get(i); indices.set(i, indices.get(j)); indices.set(j, temp);
        }
        if (size > 1 && indices.get(0) == avoidFirst) {
            int temp = indices.get(0); indices.set(0, indices.get(1)); indices.set(1, temp);
        }
        return indices;
    }
